/**
* Opens the branded invoice in a hidden iframe and triggers the browser's
* print dialog (Save as PDF). Falls back to a new tab if the iframe is blocked.
*/
function downloadInvoicePdf(inv) {
	const html = renderInvoiceHtml(inv);
	const iframe = document.createElement("iframe");
	iframe.style.position = "fixed";
	iframe.style.right = "0";
	iframe.style.bottom = "0";
	iframe.style.width = "0";
	iframe.style.height = "0";
	iframe.style.border = "0";
	document.body.appendChild(iframe);
	const doc = iframe.contentWindow?.document;
	if (!doc) {
		const w = window.open("", "_blank");
		if (w) {
			w.document.write(html);
			w.document.close();
		}
		iframe.remove();
		return;
	}
	doc.open();
	doc.write(html);
	doc.close();
	const doPrint = () => {
		try {
			iframe.contentWindow?.focus();
			iframe.contentWindow?.print();
		} finally {
			setTimeout(() => iframe.remove(), 1500);
		}
	};
	if (iframe.contentWindow?.document.readyState === "complete") setTimeout(doPrint, 400);
	else iframe.onload = () => setTimeout(doPrint, 400);
}
